(function () {
window.AINOW = window.AINOW || {};
var __exports = AINOW['data/data-albanian'] = AINOW['data/data-albanian'] || {};
const albanianPrompts = [
    {"id":"sq-1","title":"Plan Biznesi për NVM Shqiptare","prompt":"Jeni një konsulent biznesi me përvojë 15-vjeçare në këshillimin e ndërmarrjeve të vogla dhe të mesme në Shqipëri, Kosovë dhe Maqedoninë e Veriut. Hartoni një plan biznesi të detajuar për hapjen e një qendre teknologjike dhe co-working space në Prishtinë, me investim fillestar prej 80,000 euro. Plani duhet të përfshijë analizën e tregut për startupet teknologjike dhe freelancerët, projeksionet financiare për 3 vjet me pikën e barazpeshës, strategjinë e çmimeve për anëtarësimet mujore dhe hapësirat private, planin e marketingut përmes LinkedIn dhe komunitetit tech, identifikimin e mundësive të financimit nga grantet e BE-së dhe USAID, dhe planin e menaxhimit të rrezikut. Formatoni si dokument ekzekutiv të gatshëm për prezantim para investitorëve dhe bankave.","tags":["business","entrepreneurship","albania","kosovo"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},
    {"id":"sq-2","title":"Strategji Marketingu për Biznes Lokal","prompt":"Jeni specialist marketingu me ekspertizë në tregjet e Ballkanit Perëndimor. Zhvilloni një strategji të plotë marketingu 6-mujore për një restorant tradicional shqiptar në Tiranë që synon të rrisë xhiron mujore me 40%. Strategjia duhet të përfshijë analizën e konkurrencës për 5 restorante kryesore në zonë, profilin e klientit ideal, planin e rrjeteve sociale në Instagram dhe Facebook me kalendar postimesh, strategjinë e Google My Business dhe SEO lokal, programin e besnikërisë për klientë të rregullt, planin e bashkëpunimit me udhërrëfyes turistikë dhe platforma rezervimi si Booking dhe TripAdvisor, dhe buxhetin mujor të marketingut prej 800 euro. Përfshini KPI-t dhe metodat e matjes së suksesit.","tags":["marketing","business","tourism","albania"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-3","title":"Aplikim për Grant IPARD — Fermë Blegtorale","prompt":"Jeni ekspert i financimeve evropiane me njohuri të thella të programeve IPA dhe IPARD për Shqipërinë dhe Kosovën. Hartoni një aplikim të plotë për grant IPARD III për modernizimin e një ferme blegtorale familjare në rajonin e Korçës, me vlerë kërkese 120,000 euro. Aplikimi duhet të përfshijë përshkrimin e projektit me qëllime dhe objektiva SMART, analizën e situatës aktuale të fermës, justifikimin e nevojave dhe ndikimit në punësim dhe prodhim, planin e zbatimit me aktivitete dhe afate kohore, buxhetin e detajuar me justifikime, dhe treguesit e matjes së rezultateve. Formatoni sipas kërkesave standarde të AZHBR-së.","tags":["eu-grants","agriculture","rural-development","albania"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},
    {"id":"sq-4","title":"Analizë PESTEL — Treg Shqiptar","prompt":"Kryeni një analizë të plotë PESTEL për hyrjen e një kompanie të re në tregun shqiptar të shërbimeve financiare dixhitale. Për secilin faktor — Politik, Ekonomik, Social, Teknologjik, Mjedisor dhe Ligjor — analizoni gjendjen aktuale dhe trendet 2024-2026, ndikimin e mundshëm mbi biznesin, mundësitë dhe rreziqet specifike, dhe rekomandimet strategjike. Mbuloni stabilitetin politik dhe reformat e BE-së, rritjen ekonomike dhe fuqinë blerëse, demografinë dhe migracionin, penetrimin e internetit dhe smartfonëve, rregullativin e Bankës së Shqipërisë, dhe kërkesat AML/KYC. Përfundoni me një matricë prioritetesh dhe tre rekomandime kryesore strategjike.","tags":["business","strategy","albania","market-analysis"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-5","title":"Program Trajnimi — Administratë Publike Komunale","prompt":"Jeni ekspert i zhvillimit institucional dhe reformës së administratës publike në Ballkanin Perëndimor. Hartoni një program të plotë trajnimi 3-ditor për 30 nëpunës të nivelit të mesëm të administratës komunale në Kosovë, me fokus në menaxhimin e projekteve dhe transparencën. Programi duhet të përfshijë objektivat e të nxënit për çdo modul, metodologjinë me leksione dhe raste studimore, ushtrimet praktike bazuar në situata reale kosovare, testet e vlerësimit para dhe pas trajnimit, dhe planin e ndjekjes 30-ditor. Modulet kryesore: Cikli i menaxhimit të projekteve publike, Prokurimi i hapur dhe anti-korrupsioni, Shërbimi ndaj qytetarëve dhe dixhitalizimi. Formatoni si doracak trajnimi i gatshëm.","tags":["public-administration","training","governance","kosovo"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},
    {"id":"sq-6","title":"Strategji Integrimi Evropian — Komunë","prompt":"Jeni këshilltar i integrimit evropian me përvojë në projektet e twinningut dhe TAIEX në Ballkanin Perëndimor. Zhvilloni një strategji 3-vjeçare të integrimit evropian për Komunën e Tetovës në Maqedoninë e Veriut, me fokus në harmonizimin me standardet e BE-së. Strategjia duhet të adresojë 10 fushat prioritare të harmonizimit si mjedi, prokurim publik dhe e-qeverisja, planin e aktiviteteve vjetore me persona përgjegjës, nevojat për kapacitete dhe trajnime, identifikimin e burimeve të financimit nga IPA III dhe INTERREG, treguesit e progresit, dhe komunikimin me qytetarët për procesin e integrimit. Përfshini edhe analizën e sfidave specifike për komunitetin shqiptar në MV.","tags":["eu-integration","governance","north-macedonia","local-government"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},
    {"id":"sq-7","title":"Plan Zhvillimi i Turizmit Malor — Alpet Shqiptare","prompt":"Jeni konsulent turizmi me specializim në destinacionet e qëndrueshme malore të Europës Juglindore. Hartoni një plan zhvillimi të turizmit për rajonin Valbona-Theth, duke synuar rritjen e qëndrueshme të numrit të vizitorëve me 60% brenda 3 vjetësh pa dëmtuar mjedisin. Plani duhet të përfshijë auditimin e infrastrukturës ekzistuese, profilin e turistit të synuar si aventurierë dhe ekoturistë, strategjinë e çmimeve dhe paketave konkurruese, planin e marketingut dixhital përmes Instagram dhe guidave ndërkombëtare, programin e trajnimit të komunitetit lokal në gjuhë të huaja dhe shërbim mysafirësh, mekanizmat e ruajtjes mjedisore, dhe propozimin për financim nga fondet e UNWTO dhe GEF.","tags":["tourism","environment","albania","rural-development"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},
    {"id":"sq-8","title":"Kurrikul — Gjuha Shqipe për Diasporën","prompt":"Jeni pedagog specialist i gjuhësisë shqipe dhe arsimit në diasporë. Hartoni një kurrikul të plotë vjetor për mësimin e gjuhës shqipe për fëmijë të moshës 8-12 vjeç të diasporës shqiptare në Gjermani, të cilët flasin shqip në nivel fillestar-mesatar. Kurrikuli duhet të përfshijë objektivat e kompetencave gjuhësore sipas CEFR A1-A2, 36 plane mësimore javore me tema nga jeta dhe kultura shqiptare, metodologjinë për kontekstin e diasporës ku gjuha trajtohet si trashëgimi, materialet digjitale, aktivitetet kulturore me festa dhe tradita kombëtare, sistemin e vlerësimit të progresit, dhe udhëzuesin për prindërit. Formatoni si doracak i plotë mësuesi.","tags":["education","albanian-language","diaspora","culture"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-9","title":"Politikë Bujqësore — Bashki Rurale","prompt":"Jeni ekspert i politikave bujqësore me fokus në zhvillimin rural të Shqipërisë. Hartoni një politikë bujqësore gjithëpërfshirëse 5-vjeçare për Bashkinë e Skraparit, bazuar në resurset ekzistuese si blegtoria, pemëtaria dhe mjalti. Politika duhet të adresojë inventarin e burimeve bujqësore dhe potencialin e çdo sektori, skemat e subvencionimit lokal komplementar me AZHBR-në, planin e infrastrukturës për ujitje dhe rrugë rurale, programin e kooperativave bujqësore, strategjinë e markimit dhe shitjes në tregjet organike dhe eksport, trajnimin e fermerëve mbi teknikat moderne dhe standardet e BE-së, dhe planin e tërheqjes së brezave të rinj në bujqësi. Përfshini projeksionet ekonomike dhe impaktin social.","tags":["agriculture","rural-development","albania","local-government"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-10","title":"Strategji Dixhitalizimi — Institucion Publik","prompt":"Jeni konsulent i transformimit dixhital me përvojë në sektorin publik të Ballkanit Perëndimor. Hartoni një strategji dixhitalizimi 3-vjeçare për Drejtorinë Rajonale të Arsimit Parauniversitar të Shkodrës, me buxhet vjetor 50,000 euro. Strategjia duhet të përfshijë vlerësimin e nivelit aktual të dixhitalizimit, vizionin dhe objektivat strategjike, planin e veprimit vjetor, projektet prioritare si sistemi i menaxhimit të nxënësve dhe platforma e mësimit online, programin e trajnimit të mësuesve, kornizën e sigurisë kibernetike, treguesit e matjes, dhe integrimin me platformat kombëtare të e-Albania. Formatoni si dokument strategjik me plan zbatimi.","tags":["digital-transformation","public-administration","education","albania"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},
    {"id":"sq-11","title":"Raport Vlerësimi — Projekt i Financuar nga Donatorë","prompt":"Jeni vlerësues i pavarur me përvojë në vlerësimin e projekteve të financuara nga BE dhe USAID në rajonin e Ballkanit. Hartoni një raport të plotë vlerësimi të ndikimit për një projekt 3-vjeçar të zhvillimit të kapaciteteve organizative për shoqërinë civile në Kosovë, me buxhet total 500,000 euro. Raporti duhet të përfshijë metodologjinë e vlerësimit, analizën e relevantshmërisë, efektivitetit, efiçiencës, ndikimit dhe qëndrueshmërisë sipas kritereve DAC të OECD, gjetjet kryesore me evidencë, mësimet e nxjerra, dhe rekomandimet e veprueshme. Formatoni sipas standardeve ndërkombëtare të raportimit të vlerësimit.","tags":["evaluation","civil-society","donors","kosovo"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-12","title":"Plan Komunikimi Institucional — Agjenci Publike","prompt":"Jeni specialist komunikimi institucional me ekspertizë në sektorin publik të Shqipërisë. Hartoni një plan komunikimi vjetor për Agjencinë Kombëtare të Punësimit që synon rritjen e ndërgjegjësimit të shërbimeve tek të rinjtë e papunë moshës 18-30 vjeç. Plani duhet të përfshijë analizën e audiencës target dhe kanaleve të preferuara, mesazhet kryesore për çdo shërbim si trajnimet dhe ndërmjetësimi i punës, strategjinë e TikTok, Instagram dhe Facebook me kalendar mujor, planin e marrëdhënieve me mediat, materialet e komunikimit si broshura dhe video explainer, fushatën e ndërgjegjësimit me universitetet, dhe sistemin e monitorimit. Buxheti vjetor i komunikimit: 30,000 euro.","tags":["communications","public-administration","employment","albania"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-13","title":"Analizë e Politikave të Tregut të Punës — Kosovë","prompt":"Jeni analist i politikave të punësimit me fokus në Kosovën dhe rajonin. Hartoni një analizë të plotë të politikave aktuale të tregut të punës në Kosovë, me rekomandime konkrete reformuese. Analiza duhet të mbulojë gjendjen aktuale me papunësinë e lartë të të rinjve dhe grave, legjislacionin e punës dhe efektivitetin e zbatimit, vlerësimin e programeve aktive të punësimit, krahasimin me politikat e suksesshme rajonale të Maqedonisë dhe Kroacisë, boshllëqet kryesore të politikave, dhe 10 rekomandime konkrete reformuese me kosto dhe afat zbatimi. Bazoni analizën në të dhënat e ASK-së, UNDP dhe ILO.","tags":["employment","policy","kosovo","youth"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-14","title":"Strategji Eksporti — Produkte Ushqimore Shqiptare","prompt":"Jeni konsulent eksporti me specializim në agrobiznese të Ballkanit Perëndimor dhe tregjeve të BE-së. Hartoni një strategji të plotë eksporti për një kooperativë bujqësore nga Gjirokastra që prodhon vaj ulliri organik, djathë traditional dhe mjaltë, me objektiv hyrjen në tregjet gjermane dhe austriake brenda 18 muajve. Strategjia duhet të përfshijë analizën e kërkesave të tregut DACH, kërkesat rregullatore dhe certifikuese si Bio-Siegel dhe Euro-Leaf, analizën e kanaleve të shpërndarjes, strategjinë e çmimeve dhe markimit me USP-in e autenticitetit shqiptar, planin e prezantimit në panaire ndërkombëtare si Biofach Nuremberg, dhe buxhetin e eksportit me ROI të pritshëm.","tags":["export","agriculture","business","albania"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},
    {"id":"sq-15","title":"Analizë Ligjore — Korniza Startup dhe Inovacion","prompt":"Jeni jurist specialist i të drejtës tregtare dhe inovacionit me fokus në ekosistemin startup të Kosovës. Hartoni një analizë gjithëpërfshirëse të kornizës ligjore dhe rregullative që ndikon startupet dhe sipërmarrjet inovative në Kosovë, me rekomandime konkrete reformuese. Analiza duhet të mbulojë legjislacionin aktual të biznesit, boshllëqet krahasuar me vendet lider startup si Estonia dhe Letonia, mbrojtjen e pronësisë intelektuale, rregullimin e financimit me kapital rreziku, mundësitë e incentivave tatimore për R&D, dhe 8 rekomandime konkrete legjislative. Krahasoni me Ligjin Startup të Shqipërisë dhe praktikat më të mira të BE-së.","tags":["law","startups","innovation","kosovo"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-16","title":"Plane Mësimore — Rilindja Kombëtare Shqiptare","prompt":"Jeni mësues i historisë dhe kulturës shqiptare me 20 vjet përvojë. Hartoni 10 plane mësimore të plota për nxënës të klasës 9-të me temë Rilindja Kombëtare Shqiptare dhe formimi i identitetit kombëtar. Çdo plan mësimor duhet të ketë objektivat e kompetencave, materialin mësimor me burime primare dhe sekondare, metodologjinë aktive si debat dhe analizë dokumentesh, ushtrimet dhe detyrat e shtëpisë, dhe rubrikën e vlerësimit. Temat: Kongresi i Manastirit, Alfabeti shqip, Ismail Qemali, Lidhja e Prizrenit, Naim Frashëri, Sami Frashëri, Fan Noli, Luigj Gurakuqi, Çështja Shqiptare në Kongresin e Berlinit, dhe Deklarata e Pavarësisë 1912.","tags":["education","history","albanian-culture","curriculum"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-17","title":"Analizë Financiare — NVM në Vështirësi","prompt":"Jeni analist financiar me specializim në ristrukturimin e ndërmarrjeve të vogla dhe të mesme në Shqipëri. Kryeni një analizë të plotë financiare dhe hartoni planin e ristrukturimit për një kompani prodhuese me 45 punonjës nga Elbasani, që ka akumuluar borxhe ndaj furnitorëve prej 80,000 euro dhe bankës 120,000 euro pas pandemisë, por ka kontrata të reja me vlerë 200,000 euro. Analiza duhet të përfshijë diagnostikimin financiar të cash flow-it dhe likuiditetit, tre skenarë ristrukturimi, negociatat me kreditorët me propozim konkret, planin operacional të rimëkëmbjes 18-mujor, dhe projeksionet financiare me skenarë optimist, realist dhe pesimist.","tags":["finance","sme","restructuring","albania"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-18","title":"Strategji Qëndrueshmërie Mjedisore — Fabrikë Tekstili","prompt":"Jeni konsulent i qëndrueshmërisë mjedisore dhe ESG me ekspertizë në industritë prodhuese të Ballkanit Perëndimor. Hartoni një strategji të plotë qëndrueshmërie mjedisore 5-vjeçare për një fabrikë tekstili me 200 punonjës në Tiranë që synon certifikimin OEKO-TEX dhe konkurrueshmëri në tregun evropian. Strategjia duhet të përfshijë auditimin mjedisor bazë për gjurmët e karbonit dhe konsumin e ujit, objektivat SMART mjedisore, planin e investimeve për panele diellore dhe riciklim uji, planin e certifikimit OEKO-TEX 100 dhe GOTS, strategjinë e komunikimit ESG ndaj klientëve evropianë, dhe analizën kosto-benefit të investimeve mjedisore.","tags":["environment","sustainability","industry","albania"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-19","title":"Propozim Projekti — Pjesëmarrja Qytetare e Grave","prompt":"Jeni drejtor ekzekutiv i një OJQ në Kosovë me ekspertizë në demokratizim dhe të drejta civile. Hartoni një propozim të plotë projekti për financim nga Fondi Evropian për Demokraci me vlerë 150,000 euro për 24 muaj, me fokus në rritjen e pjesëmarrjes qytetare të grave rurale në vendimmarrjen lokale. Propozimi duhet të përfshijë analizën e kontekstit dhe problemit me statistika, teorinë e ndryshimit, objektivat dhe rezultatet e pritura me tregues SMART, aktivitetet e detajuara dhe planin e zbatimit, buxhetin e plotë me justifikim, planin e monitorimit dhe vlerësimit, strategjinë e qëndrueshmërisë, dhe planin e komunikimit dhe dukshmërisë.","tags":["civil-society","democracy","gender","kosovo"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-20","title":"CV Europiane — Ekonomist për Treg Gjerman","prompt":"Jeni specialist i karrierës dhe rekrutimit me përvojë në tregun e punës të Shqipërisë dhe diasporës shqiptare në Europë. Hartoni një CV të plotë në format Europass dhe stil modern për një ekonomist 32-vjeçar nga Shkodra me këto kualifikime: master ekonomi nga Universiteti i Tiranës (2016), 7 vjet përvojë në Raiffeisen Bank dhe BKT, certifikim CFA Level I (2020), anglisht C1, italisht B2, gjermanisht A2, dhe aspiratë për pozicion menaxherial në institucion financiar ndërkombëtar në Gjermani. CV-ja duhet të jetë plotësisht e formatuar sipas standardit Europass, me profil profesional bindës dhe fokus tek arritjet e matshme. Shtoni udhëzime opsionale për personalizim.","tags":["career","cv","employment","diaspora"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-21","title":"Analizë e Ndikimit Social — Skema e Ndihmës Ekonomike","prompt":"Jeni analist i politikave sociale me fokus në Shqipërinë. Kryeni një analizë të plotë të ndikimit social të reformës së skemës së ndihmës ekonomike në Shqipëri sipas Ligjit 57/2019, duke vlerësuar efektivitetin e saj në pesë vjet zbatim. Analiza duhet të mbulojë metodologjinë e mbledhjes së të dhënave, ndryshimet në mbulim dhe nivelet e përfitimeve, ndikimin tek varfëria ekstreme, efikasitetin administrativ dhe kostot, rastet e mospërfshirjes dhe mirë-synimit, krahasimin me sistemet e suksesshme rajonale, dhe rekomandimet konkrete për reformë. Bazoni analizën në të dhënat e INSTAT, BSPSH dhe Bankës Botërore.","tags":["social-policy","poverty","albania","governance"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-22","title":"Plan Biznesi — Agriturizma pranë Ohrit","prompt":"Jeni konsulent agriturizmash me ekspertizë në destinacionet rurale të Maqedonisë Veriore. Hartoni një plan të plotë biznesi për hapjen e një agriturme familjare me 8 dhoma pranë Ohrit, me produkte organike lokale dhe aktivitete turistike, me investim fillestar 60,000 euro. Plani duhet të përfshijë analizën e tregut për turistët evropianë dhe diasporën, projektet e infrastrukturës dhe renovimit, menynë me produkte lokale si peshku i Ohrit dhe verërat vendase, aktivitetet si kayaking dhe gatim tradicional, strategjinë e marketingut dixhital në Airbnb dhe Booking.com, projeksionet financiare 5-vjeçare, dhe mundësitë e financimit nga IPARD dhe LEADER.","tags":["agritourism","tourism","north-macedonia","entrepreneurship"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-23","title":"Fjalim Inaugurues — Kryetar Komune","prompt":"Jeni ekspert komunikimi politik dhe qeverisjes lokale. Shkruani një fjalim inaugurues të plotë dhe frymëzues prej rreth 2000 fjalësh për kryetarin e ri të Komunës së Ferizajt, i cili u zgjodh me platformë të zhvillimit ekonomik dhe modernizimit të shërbimeve. Fjalimi duhet të përfshijë mirënjohjen ndaj qytetarëve, vizionin 4-vjeçar për komunën, 5 prioritetet kryesore të mandatit si punësimi i të rinjve dhe infrastruktura, mesazhet ndaj komuniteteve të ndryshme, angazhimin ndaj transparencës, mesazhin drejtuar investitorëve, dhe thirrjen frymëzuese për unitet qytetar. Toni: serioz, optimist, i besueshëm dhe gjithëpërfshirës.","tags":["governance","local-government","kosovo","communications"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-24","title":"Strategji Dixhitale — Startup Fintech Kosovar","prompt":"Jeni konsulent strategjik i teknologjisë financiare me ekspertizë në tregjet e Europës Juglindore. Hartoni një strategji të plotë dixhitale dhe të hyrjes në treg për një startup fintech kosovar që ofron shërbime pagesash mobile dhe mikrokredish për bizneset e vogla informale, me financim seed prej 500,000 euro. Strategjia duhet të mbulojë analizën e tregut fintech kosovar, modelin e biznesit me revenue streams dhe unit economics, teknologjinë dhe stack-un teknologjik, strategjinë go-to-market me partneritetet kryesore, kërkesat rregullatore për licencim nga BQK, planin financiar 3-vjeçar, dhe strategjinë e shkallëzimit rajonal.","tags":["fintech","startups","digital-transformation","kosovo"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},
    {"id":"sq-25","title":"Analizë Gjuhësore — Dialektet Shqipe dhe Standardizimi","prompt":"Jeni gjuhëtar specialist i gjuhës shqipe me fokus në sociolinguistikë. Hartoni një analizë shkencore të situatës dialektore të gjuhës shqipe dhe sfidave të standardizimit, me fokus të veçantë në dallimet gegërisht-toskërisht dhe implikimet për politikat gjuhësore në Shqipëri, Kosovë dhe Maqedoninë e Veriut. Analiza duhet të mbulojë historikun e standardizimit pas Kongresit të Drejtshkrimit 1972, dallimet fonetike dhe morfologjike kryesore, statusin e varieteve gjuhësore të diasporës, sfidat e reja dixhitale të gjuhës online, rolin e Institutit të Gjuhësisë dhe ASHAK-ut, debatin akademik mbi çështje normative, dhe rekomandimet për politikat e bashkërendimit gjuhësor ndërkombëtar.","tags":["albanian-language","linguistics","culture","education"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-26","title":"Raport Transparence — OJQ Mjedisore","prompt":"Jeni ekspert qeverisje organizative me fokus në sektorin joqeveritar të Shqipërisë. Hartoni një raport vjetor transparence dhe llogaridhënieje të plotë për një OJQ mjedisore me 15 punonjës dhe buxhet vjetor 200,000 euro, sipas standardeve të Kodit të Mirëpraktikave të OJQ-ve Shqiptare. Raporti duhet të përfshijë mesazhin e drejtuesit ekzekutiv, misionin dhe vizionin, strukturën e qeverisjes, arritjet dhe impaktin vjetor me tregues të matshëm, pasqyrën financiare të thjeshtësuar, raportimin mbi donatorët dhe projektet aktive, angazhimin e vullnetarëve, sfidat e hasura, dhe planin për vitin e ardhshëm. Formatoni si dokument publik tërheqës.","tags":["civil-society","transparency","governance","albania"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-27","title":"Njësi Mësimore STEM — Uji dhe Mjedisi","prompt":"Jeni specialist kurrikuli STEM me ekspertizë në arsimin fillor të Kosovës. Hartoni një njësi mësimore STEM të plotë 4-javore me temë Uji — Burim i Jetës për nxënës të klasës 5-të në Kosovë, duke integruar shkencat natyrore, matematikën dhe teknologjinë. Njësia duhet të përfshijë 16 plane mësimore ditore prej 45 minutash, eksperimentet e thjeshta laboratorike, aktivitetet STEM me lidhje me problemet reale lokale si mungesa e ujit dhe ndotja e lumenjve, integrimin e teknologjisë me Google Earth, projektin përfundimtar të grupit, rubrikat e vlerësimit, dhe udhëzuesin e mësuesit. Bazoni në kurrikulin kombëtar të Kosovës.","tags":["education","stem","kosovo","curriculum"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-28","title":"Strategji Zhvillimi Rajonal — Rajoni i Dibrës","prompt":"Jeni ekspert zhvillimi rajonal me fokus në rajonet e pazhvilluara të Shqipërisë. Hartoni një strategji zhvillimi rajonal 7-vjeçare 2024-2030 për Rrethin e Dibrës, duke adresuar emigracionin, papunësinë dhe infrastrukturën e dobët. Strategjia duhet të mbulojë profilin socioekonomik dhe diagnostikimin rajonal, analizën SWOT, vizionin dhe prioritetet strategjike, programet konkrete për secilin prioritet, planin e investimeve publike me burime financimi nga IPA dhe EBRD, mekanizmin e qeverisjes dhe zbatimit, sistemin e monitorimit me tregues output dhe impakt, dhe planin e komunikimit me palët e interesit.","tags":["regional-development","albania","governance","eu-integration"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-29","title":"Udhëzues Praktik — Shërbimet e e-Albania","prompt":"Jeni specialist i qeverisjes elektronike dhe shërbimeve dixhitale publike. Hartoni një udhëzues praktik gjithëpërfshirës dhe të thjeshtë për qytetarët shqiptarë mbi përdorimin e portalit e-Albania dhe të gjitha shërbimet elektronike kryesore. Udhëzuesi duhet të mbulojë regjistrimin dhe aktivizimin e llogarisë hap-pas-hapi, 20 shërbimet më të përdorura si gjendja civile, pasaportat, certifikatat dhe lejet, zgjidhjen e problemeve teknike të shpeshta, udhëzimin për persona të moshuar, privatësinë dhe sigurinë, dhe shërbimin e ndihmës. Formatoni me hapa të qartë dhe gjuhë të thjeshtë jo-teknike. Shtoni FAQ me 15 pyetje të shpeshta.","tags":["digital-transformation","e-government","albania","citizens"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-30","title":"Analizë Konkurrenciale — Sektori Hotelier Shqiptar","prompt":"Jeni analist tregu me specializim në industrinë hoteliere të Shqipërisë. Kryeni një analizë të plotë konkurrenciale të sektorit hotelier shqiptar për vitin 2024, duke u fokusuar në segmentin e hoteleve 4-5 yje. Analiza duhet të mbulojë panoramën e industrisë me numrin e hoteleve dhe normën e zënies, profilimet e 10 konkurrentëve kryesorë, analizën e pesë forcave të Porterit, trendet e kërkesës dhe sezonalitetin, krahasimin e çmimeve dhe standardeve, boshllëqet dhe mundësitë e tregut, dhe rekomandimet strategjike për operatorët vendas. Bazoni në të dhënat e INSTAT dhe UNWTO.","tags":["tourism","market-analysis","hospitality","albania"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-31","title":"Plan Veprimi Anti-Korrupsion — Bashki","prompt":"Jeni ekspert qeverisje dhe anti-korrupsion me fokus në qeverisjen lokale të Shqipërisë. Hartoni një plan veprimi anti-korrupsion 2-vjeçar për Bashkinë e Vlorës, bazuar në gjetjet e auditimit dhe standardet e GRECO. Plani duhet të përfshijë diagnostikimin e rreziqeve sipas fushave si prokurimi dhe planifikimi urban, masat parandaluese konkrete, mekanizmat e kontrollit të brendshëm dhe jashtëm, sistemin e denoncimit të korrupsionit dhe mbrojtjen e informatorëve, programin e trajnimit të nëpunësve, angazhimin e shoqërisë civile dhe medias, dhe treguesit e matjes së progresit. Mbuloni edhe implikimet e procesit të integrimit evropian.","tags":["anti-corruption","governance","local-government","albania"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-32","title":"Tekst Prezantimi — Produkte Ushqimore Shqiptare për Eksport","prompt":"Jeni copywriter me specializim në markimin e produkteve autentike ballkanase për tregjet ndërkombëtare. Shkruani tekstet e plota të prezantimit për tre produkte ushqimore tradicionale shqiptare — vaj ulliri i virgjër ekstra nga Berati, raki tradicionale nga Korça, dhe djathë i bardhë artizanal nga Shkodra — për tregun gjerman. Për secilin produkt shkruani historinë dhe lidhjen me terroir-in shqiptar, përshkrimin e shijes dhe karakteristikave, udhëzimet e konsumit, informacionin nutricion dhe certifikimet, dhe sloganin e markës. Toni: autentik, premium, me narrativ kulturor. Shkruani paralel në shqip dhe gjermanisht. Përfshini udhëzime packaging sipas standardeve BE.","tags":["marketing","export","albanian-culture","food"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-33","title":"Raport i Gjendjes Ekonomike — Kosovë","prompt":"Jeni ekonomist me fokus në ekonomitë e vogla të hapura të Europës Juglindore. Hartoni një raport të plotë të gjendjes ekonomike të Kosovës për vitin 2024, të stilizuar si raport i Bankës Qendrore. Raporti duhet të mbulojë ecurinë makroekonomike me rritjen e GDP, inflacionin dhe papunësinë, analizën e sektorëve kryesorë si ndërtimtaria dhe remitancat, treguesit fiskalë, sistemin financiar dhe qëndrueshmërinë bankare, tregtinë e jashtme dhe investimet direkte, sfidat strukturore si informaliteti, dhe perspektivat dhe rreziqet 2025-2026. Bazoni në të dhënat e BQK-së, ASK-së dhe FMN-së.","tags":["economics","kosovo","finance","policy"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-34","title":"Propozim Partneriteti Publik-Privat — Qendër Sportive","prompt":"Jeni ekspert i partneriteteve publik-private me ekspertizë në infrastrukturën e Ballkanit Perëndimor. Hartoni një propozim të plotë PPP për ndërtimin dhe operimin e një qendre sportive bashkëkohore në Elbasan, me kapital privat 3,000,000 euro dhe kontribut komunal me tokën dhe lejen e ndërtimit. Propozimi duhet të përfshijë modelin BOT të propozuar, analizën e fizibilitetit financiar me kthimin e investimit, kuadrin kontraktual dhe ndarjen e rreziqeve, procedurën e prokurimit sipas ligjit shqiptar PPP, garancitë dhe sigurimet, mekanizmin e mbikëqyrjes publike, vlerën sociale dhe ekonomike me punësimin e krijuar, dhe planin e transferimit të pronësisë pas 25 vjetësh.","tags":["ppp","infrastructure","local-government","albania"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-35","title":"Strategji Dixhitalizimi — Shkollë e Mesme","prompt":"Jeni specialist i teknologjisë arsimore. Hartoni një strategji dixhitalizimi 3-vjeçare për një shkollë të mesme me 800 nxënës dhe 60 mësues në Prizren, me buxhet vjetor 15,000 euro. Strategjia duhet të përfshijë vlerësimin e nivelit aktual dixhital, vizionin dhe objektivat, planin e investimeve për pajisje dhe WiFi, krahasimin e platformave mësimore Google Workspace dhe Microsoft 365, programin e trajnimit të mësuesve me 25 orë vit, integrimin e kompetencave dixhitale në kurrikul, politikën e sigurisë kibernetike, dhe treguesit sipas DigComp 2.2. Përfshini udhëzues zbatimi hap-pas-hapi.","tags":["education","digital-transformation","kosovo","technology"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-36","title":"Letër Motivimi — Pozicion në Institucion Ndërkombëtar","prompt":"Jeni specialist karriere me përvojë në rekrutimin ndërkombëtar. Shkruani një letër motivimi të plotë dhe bindëse për pozicionin e Analistit të Programeve në UNDP Kosovë për një kandidate shqiptare nga Shkupi, 28 vjeçe, me master nga Universiteti i Vjenës në Politika Publike, 4 vjet përvojë në OJQ lokale në fushën e qeverisjes lokale dhe financimeve evropiane, gjuhë angleze C2, frëngjisht B2, dhe njohuri të thella të kontekstit kosovar dhe maqedonas. Letra duhet të jetë maksimum 450 fjalë, të nënvizojë përputhjen me kërkesat e pozicionit, dhe të pasqyrojë motivimin autentik. Formatoni sipas standardeve të UN.","tags":["career","employment","international-organizations","north-macedonia"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-37","title":"Strategji Zhvillimi i Kapaciteteve — OJQ","prompt":"Jeni konsulent zhvillimi organizativ me ekspertizë në sektorin joqeveritar të Ballkanit Perëndimor. Hartoni një strategji 2-vjeçare të zhvillimit të kapaciteteve për një OJQ të drejtave të njeriut me 8 punonjës dhe buxhet vjetor 100,000 euro në Tetovë. Strategjia duhet të përfshijë vlerësimin e kapaciteteve aktuale organizative sipas pesë shtyllave: qeverisja, burimet njerëzore, financat, programet dhe komunikimi. Për çdo fushë: objektivat e kapaciteteve, aktivitetet e ndërhyrjes, burimet e nevojshme, dhe treguesit e matjes. Përfshini edhe planin e mentorimit dhe partneriteteve strategjike, strategjinë e diversifikimit të financimit, dhe planin e suksesionit drejtues.","tags":["civil-society","capacity-building","north-macedonia","governance"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-38","title":"Analiza e Sektorit Agro-Ushqimor — Shqipëri","prompt":"Jeni analist i sektorit agro-ushqimor me fokus në zinxhirët e vlerës të Shqipërisë. Kryeni një analizë të plotë të sektorit agro-ushqimor shqiptar me fokus te mundësitë e rritjes dhe sfidave strukturore. Analiza duhet të mbulojë panoramën e sektorit me kontributin në GDP dhe punësim, analizën e zinxhirëve kryesorë të vlerës si ullishtet, perimet dhe blegtoria, boshllëqet e infrastrukturës si ruajtja frigorifike dhe procesimi, pengesat rregullatore dhe fitosanitare për eksport, mundësitë nga tregjet e specializuara dhe GI-të si SHGJG, krahasimin me Malin e Zi dhe Maqedoninë, dhe rekomandimet e politikave. Bazoni në të dhënat e FAO dhe INSTAT.","tags":["agriculture","market-analysis","albania","export"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-39","title":"Plan Komunikimi — Fushatë Sensibilizimi Shëndetësor","prompt":"Jeni specialist komunikimi shëndetësor me fokus në Shqipërinë dhe Kosovën. Hartoni një plan të plotë komunikimi për një fushatë sensibilizimi 3-mujore mbi parandalimin e diabetit tip 2, drejtuar burrave dhe grave moshës 40-60 vjeç në zonat urbane të Shqipërisë. Plani duhet të përfshijë analizën e audiencës dhe barrierat ndaj ndryshimit të sjelljes, mesazhet kryesore të ndërhyrjes shëndetësore, strategjinë e kanaleve si televizionet lokale, Facebook dhe mjekët familjarë, materialet e komunikimit si postera, fletëpalosje dhe video, partneret institucionale si Ministria e Shëndetësisë dhe ISHP, buxhetin 20,000 euro, dhe sistemin e matjes së ndikimit të fushatës.","tags":["health","communications","albania","public-health"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-40","title":"Rregullore e Brendshme — Kooperativë Bujqësore","prompt":"Jeni jurist specialist i të drejtës kooperativiste dhe bujqësore të Shqipërisë. Hartoni një rregullore të brendshme të plotë dhe ligjërisht korrekte për themelimin dhe funksionimin e një kooperative bujqësore me 25 anëtarë fermerë vreshturish në rajonin e Beratit, sipas Ligjit 8765/2001 dhe ndryshimeve të tij. Rregullorja duhet të përfshijë dispozitat e përgjithshme dhe qëllimin, kushtet e anëtarësimit dhe procedurën e pranimit, të drejtat dhe detyrimet e anëtarëve, strukturën e organeve drejtuese dhe mënyrën e zgjedhjes, procedurën e vendimmarrjes dhe kuorumet, menaxhimin financiar dhe ndarjen e fitimeve, procedurat disiplinore dhe të largimit nga anëtarësia, dhe dispozitat e shpërbashkimit. Formatoni si akt juridik i gatshëm për nënshkrim.","tags":["agriculture","law","cooperative","albania"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-41","title":"Strategji e-Commerce — Artizanë Shqiptarë","prompt":"Jeni konsulent e-commerce me ekspertizë në tregtinë online të produkteve artizanale dhe kulturore. Hartoni një strategji të plotë e-commerce për një grup prej 12 artizanësh shqiptarë nga Gjirokastra dhe Kruja që prodhojnë produkte tradicionale si qilima, argjendaria dhe gdhendja, që dëshirojnë të shesin online në tregjet ndërkombëtare. Strategjia duhet të mbulojë zgjedhjen e platformës si Etsy, Amazon Handmade ose faqe e pavarur, fotografinë dhe prezantimin e produkteve, çmimet dhe menaxhimin e shpenzimeve të transportit ndërkombëtar, strategjinë e SEO dhe rrjeteve sociale, menaxhimin e porosive dhe kthimeve, mbrojten e pronësisë intelektuale, dhe planin e rritjes 2-vjeçar.","tags":["e-commerce","artisans","albanian-culture","entrepreneurship"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-42","title":"Analizë e Sistemit Arsimor — Kosovë","prompt":"Jeni ekspert i politikave arsimore me fokus në sistemin arsimor të Kosovës. Hartoni një analizë kritike dhe gjithëpërfshirëse të sistemit arsimor parauniversitar të Kosovës, duke identifikuar sfidat kryesore strukturore dhe duke propozuar reforma. Analiza duhet të mbulojë treguesit kryesorë arsimore si shkalla e braktisjes dhe performanca në PISA, analizën e cilësisë mësimore dhe trajnimit të mësuesve, infrastrukturën dhe burimet shkollore, pabarazitë rajonale dhe sociale, kurrikulin dhe përputhjen me nevojat e tregut të punës, financimin e arsimit krahasuar me standardet e BE-së, dhe 10 rekomandime prioritare me kosto dhe afat zbatimi. Bazoni në raportet e MAShTI-t, Bankës Botërore dhe OECD.","tags":["education","policy","kosovo","governance"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-43","title":"Propozim Teknik — Sistemi i Menaxhimit të Mbetjeve","prompt":"Jeni inxhinier mjedisor dhe konsulent i menaxhimit të mbetjeve me ekspertizë në vendet e Ballkanit. Hartoni një propozim teknik të plotë për implementimin e sistemit të menaxhimit të integruar të mbetjeve të ngurta për Komunën e Gjilanit me 90,000 banorë, në përputhje me Direktivën BE të Mbetjeve. Propozimi duhet të përfshijë diagnostikimin e situatës aktuale të menaxhimit të mbetjeve, dizajnin e sistemit të ri me ndarjen sipas burimit, planin e infrastrukturës si pikat e grumbullimit dhe stacioni i transferit, programin e edukimit qytetar, modelin ekonomik me tarifat dhe kostot operative, planin e zbatimit me faza, dhe burimet e financimit nga IPA III dhe WBIF.","tags":["environment","infrastructure","kosovo","local-government"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-44","title":"Kuadër Kompetencash — Nëpunës Civil Kosovar","prompt":"Jeni ekspert i burimeve njerëzore dhe reformës së shërbimit civil me fokus në Kosovën. Hartoni një kuadër të plotë kompetencash për nëpunësit civilë të nivelit të mesëm drejtues në administratën publike kosovare, sipas standardeve të SIGMA dhe OECD. Kuadri duhet të përfshijë 5 kompetenca kyçe me 4-5 tregues sjelljeje secila, shpërndarjen sipas niveleve nga fillestar tek ekspert, metodologjinë e vlerësimit të kompetencave, lidhjen me sistemin e vlerësimit të performancës, dhe udhëzuesin e zbatimit për menaxherët. Kompetencave bazë: lidershipi, menaxhimi i rezultateve, orientimi ndaj qytetarit, integriteti dhe etika, dhe bashkëpunimi ndërinstitucional.","tags":["public-administration","human-resources","kosovo","governance"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-45","title":"Plan i Menaxhimit të Destinacionit Turistik","prompt":"Jeni ekspert i menaxhimit të destinacioneve turistike me fokus në destinacionet kulturore të Ballkanit. Hartoni një plan të plotë menaxhimi të destinacionit turistik për qytetin historik të Beratit — UNESCO, për periudhën 2024-2027. Plani duhet të përfshijë analizën e turistëve aktualë dhe potencialë, kapacitetin mbajtës të destinacionit, strategjinë e menaxhimit të flukseve vizitorësh, programin e interpretimit kulturor dhe trashëgimisë, planin e trajnimit të gjidave lokale, strategjinë e desezionalizimit, sistemin e monitorimit të ndikimit turistik, bashkëpunimin ndërinstitucional midis bashkisë dhe operatorëve, dhe planin e komunikimit dhe markimit si Brand Albania.","tags":["tourism","cultural-heritage","albania","regional-development"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},
    {"id":"sq-46","title":"Propozim Ligji — Mbrojtja e Konsumatorit Online","prompt":"Jeni jurist specialist i të drejtës dixhitale dhe mbrojtjes së konsumatorit me njohuri të legjislacionit të BE-së. Hartoni një propozim ligji gjithëpërfshirës për mbrojtjen e konsumatorit në tregtinë elektronike për Shqipërinë, në harmoni me Direktivën e BE-së 2019/770 dhe 2019/771. Propozimi duhet të përfshijë shpjegimin e nevojës dhe qëllimit, analizën e boshllëqeve në legjislacionin aktual shqiptar, dispozitat thelbësore të propozuara me draftin e neneve kryesore, mekanizmat e zbatimit dhe sanksionet, rolin e autoritetit rregullues, ndikimin mbi bizneset vendase dhe importin, dhe planin e harmonizimit gradual. Formatoni si dokument politikash legjislative me draft nene.","tags":["law","digital-transformation","consumer-protection","albania"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-47","title":"Strategji Mësimdhënieje — Gjuha Shqipe si Gjuhë Amtare","prompt":"Jeni pedagog specialist i didaktikës së gjuhës shqipe me fokus në qasjet bashkëkohore. Hartoni një strategji gjithëpërfshirëse të mësimdhënies së gjuhës shqipe si gjuhë amtare për nxënës të klasave 6-9 në shkollat e Maqedonisë Veriore, duke adresuar sfidat specifike të kontekstit shqiptar në MV. Strategjia duhet të mbulojë qasjet komunikuese dhe funksionale të mësimdhënies, integrimin e kulturës dhe literaturës shqiptare, metodat e vlerësimit formativ dhe sumativ, materialet dhe burimet mësimore të disponueshme, strategjitë e diferencimit për nxënësit e ndryshëm, programin e zhvillimit profesional të mësuesve, dhe bashkëpunimin me prindërit. Mbuloni edhe integrimin e teknologjisë mësimore.","tags":["education","albanian-language","north-macedonia","curriculum"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-48","title":"Raport Monitorimi — Zbatimi i Strategjisë Kombëtare","prompt":"Jeni ekspert monitorimi dhe vlerësimi i politikave publike. Hartoni një raport të plotë monitorimi vjetor të zbatimit të Strategjisë Kombëtare për Zhvillim dhe Integrim të Shqipërisë 2022-2030, sipas metodologjisë standarde. Raporti duhet të përfshijë metodologjinë e monitorimit, progresin e zbatimit sipas prioriteteve strategjike me trafikun e gjelbër-verdhë-kuq për çdo tregues, analizën e pengesave dhe rreziqeve për zbatim, kapacitetin e zbatimit institucional, konformitetin e buxhetit me prioritetet strategjike, rekomandimet e ndërhyrjes, dhe shtojcën statistikore me tabelat e treguesve. Formatoni sipas kërkesave të Sekretariatit të Integrimit Evropian.","tags":["policy","monitoring","albania","eu-integration"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-49","title":"Biznes Plan — Klinikë Dentare Private","prompt":"Jeni konsulent biznesi shëndetësor me ekspertizë në hapjen dhe menaxhimin e praktikave dentare private në Shqipëri dhe Kosovë. Hartoni një plan të plotë biznesi për hapjen e një klinike dentare moderne me 3 karrige dhe 2 dentistë në Prishtinë, me investim fillestar 120,000 euro. Plani duhet të përfshijë analizën e tregut dentar kosovar me konkurrencën dhe çmimet, planin e infrastrukturës dhe pajisjet e nevojshme, strukturën organizative dhe kualifikimet e stafit, listën e shërbimeve dhe çmimeve, strategjinë e marketingut dixhital dhe rekomandimeve, projeksionet financiare 5-vjeçare me break-even analysis, kërkesat e licencimit nga Ministria e Shëndetësisë, dhe planin e menaxhimit të rrezikut.","tags":["business","healthcare","entrepreneurship","kosovo"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-50","title":"Analizë Politike — Diaspora Shqiptare dhe Kontributi Zhvillimor","prompt":"Jeni studiues i migracionit dhe politikave të diasporës me fokus në diasporën shqiptare globale. Hartoni një analizë të plotë të kontributit ekonomik dhe social të diasporës shqiptare dhe rekomandime politikash për maksimizimin e tij. Analiza duhet të mbulojë profilin demografik të diasporës shqiptare sipas vendeve pritëse, flukset e remitancave dhe trendet 2015-2024, investimet e diasporës dhe boshllëqet e angazhimit, transfertat e njohurive dhe kapitalit njerëzor, politikat ekzistuese për diasporën dhe efektivitetin e tyre, praktikat më të mira ndërkombëtare si India, Maroku dhe Filipinet, dhe 10 rekomandime konkrete politikash duke përfshirë bondet e diasporës, taksimin preferencial dhe programet e kthimit.","tags":["diaspora","migration","policy","albania"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-51","title":"Plan Aksioni Klimatik — Bashki Bregdetare","prompt":"Jeni ekspert i politikave klimatike dhe përshtatjes urbane me fokus në qytetet bregdetare të Mesdheut. Hartoni një plan aksioni klimatik lokal për Bashkinë e Sarandës, duke adresuar rreziqet specifike të ndryshimit klimatik si rritja e nivelit të detit, valët e nxehtësisë dhe thatësira. Plani duhet të përfshijë vlerësimin e cenueshmërisë klimatike me hartëzimin e rreziqeve, objektivat e reduktimit të emetimeve të GHG për 2030 dhe 2050, masat e përshtatjes sektoriale për turizmin, bujqësinë dhe infrastrukturën, programin e energjisë së rinovueshme dhe efikasitetit energjetik, financimin klimatik nga GCF dhe fondet e BE-së, mekanizmin e qeverisjes klimatike lokale, dhe planin e edukimit qytetar. Formatoni sipas standardeve të Konventës së Paktit të Kryebashkiakëve.","tags":["climate","environment","local-government","albania"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-52","title":"Analizë e Tregut të Pasurive të Paluajtshme — Tiranë","prompt":"Jeni analist i tregut të pasurive të paluajtshme me specializim në tregjet e Europës Juglindore. Kryeni një analizë të plotë të tregut të pasurive të paluajtshme rezidenciale të Tiranës për periudhën 2022-2024, me projeksione për 2025-2026. Analiza duhet të mbulojë trendet e çmimeve sipas lagjeve dhe kategorive, faktorët e ofertës si lejet e ndërtimit dhe projektet e reja, faktorët e kërkesës si blerja e diasporës dhe migrimi i brendshëm, ndikimin e normave të interesit dhe kushteve të kreditimit bankar, krahasimin me Prishtinën dhe Shkupin, rreziqet e spekulimit dhe flluskat e mundshme, dhe implikimet e politikave rregullatore. Bazoni në të dhënat e Bankës së Shqipërisë dhe INSTAT.","tags":["real-estate","market-analysis","albania","finance"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-53","title":"Program Mentoratë — Sipërmarrës të Rinj Shqiptarë","prompt":"Jeni koordinator i programeve të mentoratës dhe sipërmarrjes rinore me ekspertizë në ekosistemet e startupeve të Ballkanit. Hartoni një program të plotë mentoratë 6-mujor për 20 sipërmarrës të rinj shqiptarë moshës 20-30 vjeç nga Shqipëria, Kosova dhe Maqedonia e Veriut. Programi duhet të përfshijë kriteret dhe procesin e përzgjedhjes për sipërmarrësit dhe mentorët, strukturën e seancave të mentoratës — individuale dhe grupore, kurrikulin e zhvillimit të aftësive sipërmarrëse me modulet si plani i biznesit, financimi dhe marketingu, eventin e demo day-t final, sistemin e çiftimit sipërmarrës-mentor, mekanizmin e ndjekjes pas programit, dhe modelin e financimit dhe qëndrueshmërisë. Formatoni si manual programi i gatshëm.","tags":["entrepreneurship","youth","mentoring","regional-development"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-54","title":"Studim Fizibiliteti — Fermë Fotovoltaike","prompt":"Jeni inxhinier energjetik dhe konsulent i projekteve të energjisë së rinovueshme me fokus në Shqipërinë dhe Kosovën. Kryeni një studim të plotë fizibiliteti për instalimin e një ferme fotovoltaike prej 5 MW në tokën bujqësore të papërdorshme pranë Lushnjës, me investim të parashikuar 4,500,000 euro. Studimi duhet të përfshijë analizën e rrezatimit diellor dhe burimet e resursit, dizajnin teknik me llojet e panelave dhe inverterëve, kostot CAPEX dhe OPEX, modelin financiar me NPV dhe IRR, procedurat e licencimit tek ERE dhe lidhjen me rrjetin elektrik të OST, mundësitë e financimit si BERZH dhe IFC, rreziqet teknike dhe rregullatore, dhe krahasimin me alternativat e tjera të energjisë së rinovueshme.","tags":["energy","renewable-energy","investment","albania"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-55","title":"Strategji Kulturore — Trashëgimia Materiale dhe Jomateriale","prompt":"Jeni ekspert i trashëgimisë kulturore dhe politikave kulturore me fokus në Shqipërinë dhe rajonin. Hartoni një strategji gjithëpërfshirëse 5-vjeçare për ruajtjen dhe promovimin e trashëgimisë kulturore materiale dhe jomateriale të Shqipërisë, duke shfrytëzuar mundësitë e turizmit kulturor dhe ekonomisë kreative. Strategjia duhet të mbulojë inventarizimin dhe dixhitalizimin e trashëgimisë, programet e restaurimit dhe konservimit, integrimin e trashëgimisë jomateriale si iso-polifonia dhe vallet tradicionale, zhvillimin e turizmit kulturor dhe itinerarëve tematihe, ekonominë kreative dhe artizanatin tradicional, edukimin kulturor dhe ndërgjegjësimin, bashkëpunimin ndërkombëtar si UNESCO dhe Creative Europe, dhe financimin nga programet e BE-së. Bazoni në Konventën UNESCO 2003.","tags":["culture","cultural-heritage","tourism","albania"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},
    {"id":"sq-56","title":"Raport i Progresit BE — Vlerësim Vendor","prompt":"Jeni analist i procesit të integrimit evropian me fokus në Shqipërinë. Hartoni një analizë të pavarur të progresit të Shqipërisë në procesin e anëtarësimit të BE-së për vitin 2024, e strukturuar si vlerësim vendor paralel me raportin e Komisionit Evropian. Raporti duhet të mbulojë progresin në kriteret politike si demokracia dhe sundimi i ligjit, progresin sipas kapitujve të negociatave me fokus tek ato prioritare si drejtësia dhe korrupsioni, reformën e sistemit gjyqësor dhe prokurorisë, luftën kundër krimit të organizuar, lirinë e medias dhe lirinë e shprehjes, të drejtat e njeriut dhe grupet e cenueshme, dhe pikëpamjet e shoqërisë civile. Formatoni sipas strukturës standarde të raporteve të KE.","tags":["eu-integration","governance","albania","policy"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-57","title":"Manual Trajnimi — Negocim dhe Zgjidhje Konfliktesh","prompt":"Jeni trajner i specializuar në negocim, mediacion dhe zgjidhje konstruktive të konflikteve me ekspertizë në kontekstin e Ballkanit. Hartoni një manual të plotë trajnimi 2-ditor për 25 drejtues të nivelit të mesëm nga sektori publik dhe privat i Kosovës mbi teknikat efektive të negocimit dhe zgjidhjes së konflikteve profesionale. Manuali duhet të përfshijë materialin teorik për stilet e negocimit dhe dinamikat e konfliktit, 8 skenarë praktikë me role-play bazuar në situata reale kosovare si negociata kontraktuale, konflikte ndëretnike pune dhe mediacion komunal, teknikat BATNA dhe ZOPA, ushtrimet praktike me feedback strukturuar, buletinin e mjeteve dhe teknikave, dhe udhëzuesin e lehtësuesit. Formatoni si doracak i gatshëm.","tags":["training","negotiation","conflict-resolution","kosovo"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-58","title":"Strategji e Turizmit të Qëndrueshëm — Rajoni i Ohrit","prompt":"Jeni konsulent i turizmit të qëndrueshëm me ekspertizë në destinacionet e trashëgimisë UNESCO. Hartoni një strategji të qëndrueshme turistike 5-vjeçare për rajonin e Ohrit në Maqedoninë e Veriut, duke balancuar rritjen ekonomike me mbrojtjen e trashëgimisë natyrore dhe kulturore. Strategjia duhet të mbulojë analizën e ndikimit aktual turistik në ekosistemit e Ohrit, kapacitetin mbajtës me tregues specifik, diversifikimin e ofertës turistike përtej sezonit veror, zhvillimin e turizmit kulturor shqiptar dhe maqedonas në rajon, programin e menaxhimit të mbetjeve dhe mbrojtjes së ujit, standardet e akomodimit ekologjik, bashkëpunimin ndërkufitar me Shqipërinë për destinacionin e pellgut të Ohrit, dhe mekanizmat e financimit nga UN Environment dhe GEF.","tags":["tourism","environment","north-macedonia","sustainability"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-59","title":"Plan i Zhvillimit Profesional — Mësues","prompt":"Jeni koordinator i zhvillimit profesional të mësuesve me ekspertizë në sistemet arsimore të Ballkanit. Hartoni një plan të plotë zhvillimi profesional vjetor për mësuesit e shkollave fillore dhe të mesme të ulëta të komunës së Pejës në Kosovë. Plani duhet të përfshijë vlerësimin e nevojave të zhvillimit profesional sipas kompetencave të mësuesit, programin e trajnimeve të obligueshme dhe zgjedhore me orari dhe tematikën, mentoratën mes kolegëve dhe komunitetin profesional të mësimit, vizitat studimore ndërkombëtare dhe shkëmbimin e praktikave, platformën online të të nxënit, sistemin e pikëve të akreditimit, lidhjen me rritjen e karrierës dhe pagën, dhe buxhetin komunal të zhvillimit profesional.","tags":["education","professional-development","kosovo","teachers"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-60","title":"Analiza e Zinxhirit të Vlerës — Sektori i Bletarisë","prompt":"Jeni ekspert i zhvillimit të zinxhirëve të vlerës bujqësore me fokus në sektore me potencial eksporti në Shqipërinë. Kryeni një analizë të plotë të zinxhirit të vlerës së sektorit të bletarisë shqiptare, duke identifikuar mundësitë për rritje të vlerës së shtuar dhe hyrje në tregjet premium ndërkombëtare. Analiza duhet të mbulojë mapimin e aktorëve të zinxhirit nga bletari tek konsumatori final, analizën e kostove dhe marzheve në çdo hallkë, standardet e cilësisë dhe certifikimet e nevojshme si origjina e mbrojtur, pengesat strukturore për zhvillim, mundësitë e agregimit dhe kooperativizmit, tregjet e synuara si mjalti monofloral dhe organik premium, dhe rekomandimet e ndërhyrjes me prioritizim. Bazoni në të dhënat e MBUZOUK dhe FAO.","tags":["agriculture","value-chain","export","albania"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-61","title":"Propozim Politike — Arsimi i Fëmijëve me Nevoja të Veçanta","prompt":"Jeni ekspert i arsimit gjithëpërfshirës dhe të drejtave të fëmijëve me aftësi të kufizuara me fokus në sistemet arsimore të Kosovës dhe Shqipërisë. Hartoni një propozim politike gjithëpërfshirës për reformimin e sistemit të arsimit gjithëpërfshirës në Kosovë, sipas Konventës së OKB-së për të Drejtat e Personave me Aftësi të Kufizuara. Propozimi duhet të përfshijë diagnostikimin e situatës aktuale me shifra dhe boshllëqe, parimet e arsimit gjithëpërfshirës sipas CRPD, rekomandimet e politikave për infrastrukturën shkollore, trajnimin e mësuesve, asistentët e arsimit special, bashkëpunimin shërbimeve sociale-arsimore-shëndetësi, financimin e nevojshëm, dhe planin e zbatimit gradual me faza.","tags":["education","inclusion","disability","kosovo"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-62","title":"Raport Biznesor — Analiza e Mundësive Investimi","prompt":"Jeni analist investimesh me ekspertizë në tregjet e Ballkanit Perëndimor. Hartoni një raport gjithëpërfshirës të mundësive të investimit në sektorin e agroturizmit dhe ushqimit organik në Shqipëri për investitorë të huaj dhe të diasporës, me fokus në periudhën 2024-2027. Raporti duhet të mbulojë treguesit makroekonomikë dhe klimën e investimeve, kuadrin ligjor dhe incentivat fiskale për investitorët e huaj, analizën e sektorit me mundësitë dhe rreziqet, profilet e pesë mundësive konkrete investimi si pako investimi me vlerë, normë kthimi të parashikuar dhe hapat e zbatimit, infrastrukturën mbështetëse si bankat dhe shërbimet ligjore, dhe burimet e informacionit dhe kontaktet institucionale. Formatoni si raport investimi professional.","tags":["investment","agriculture","tourism","albania"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-63","title":"Strategji Shëndetësi Digjitale — Sistemit Spitalor","prompt":"Jeni konsulent i shëndetësisë dixhitale me ekspertizë në transformimin e sistemeve spitalore në vendet në zhvillim. Hartoni një strategji dixhitalizimi 4-vjeçare për Spitalin Rajonal të Gjirokastrës, me 300 shtretër dhe 450 punonjës, duke adresuar efikasitetin operacional dhe cilësinë e shërbimit. Strategjia duhet të përfshijë vlerësimin e nivelit aktual dixhital, vizionin dhe objektivat klinike të digjitalizimit, projektet prioritare si HIS, telemedicina dhe imaging dixhital, planin e trajnimit të personelit mjekësor dhe administrativ, kuadrin e mbrojtjes së të dhënave shëndetësore sipas GDPR-shqiptar, integrimin me sistemin kombëtar të shëndetësisë, financimin nga BERZH dhe IFC, dhe metodologjinë e vlerësimit të ndikimit klinik.","tags":["healthcare","digital-transformation","albania","public-health"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-64","title":"Hartim Kontrate — Marrëveshje Bashkëpunimi Ndërkomunal","prompt":"Jeni jurist specialist i të drejtës publike dhe qeverisjes lokale me fokus në Shqipërinë. Hartoni një marrëveshje të plotë bashkëpunimi ndërkomunal midis Bashkisë së Korçës dhe Bashkisë së Pogradecit për menaxhimin e përbashkët të mbetjeve urbane dhe shërbimeve mjedisore, sipas Ligjit 139/2015 për Qeverisjen Vendore. Kontrata duhet të përfshijë palët dhe kompetencat ligjore, objektin dhe fushëveprimin e bashkëpunimit, strukturën e qeverisjes së shërbimit të përbashkët, ndarjen e kostove dhe burimeve njerëzore, mekanizmin e kontabilizimit dhe auditimit të pavarur, procedurat e zgjidhjes së mosmarrëveshjeve, kushtet e ndryshimit dhe përfundimit të marrëveshjes, dhe dispozitat kalimtare. Formatoni si akt ligjor i gatshëm për miratim nga këshillat bashkiakë.","tags":["law","local-government","inter-municipal","albania"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-65","title":"Analizë e Barazisë Gjinore — Sektori Publik","prompt":"Jeni ekspert i barazisë gjinore dhe politikave sociale me fokus në Shqipërinë dhe Maqedoninë e Veriut. Kryeni një analizë të plotë të barazisë gjinore në sektorin publik të Shqipërisë, me fokus të veçantë në qeverisjen lokale dhe shërbimin civil. Analiza duhet të mbulojë analizën statistikore të përfaqësimit gjinor sipas niveleve dhe sektorëve, pagën gjinore dhe boshllëqet e promovimit, politikat ekzistuese të barazisë gjinore dhe zbatimin e tyre, analizën e pengesave strukturore dhe kulturore, praktikat e mira vendase dhe ndërkombëtare, krahasimin me standardet e Konventës CEDAW dhe platformat e BE-së, dhe 12 rekomandime konkrete politikash me afat dhe burim financiar. Bazoni në të dhënat e INSTAT dhe raporteve të UN Women.","tags":["gender","public-administration","policy","albania"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-66","title":"Plan Emergjence — Menaxhimi i Katastrofave Natyrore","prompt":"Jeni ekspert i menaxhimit të emergjencave dhe uljes së rrezikut nga fatkeqësitë me fokus në Shqipërinë. Hartoni një plan të plotë emergjence komunale për Bashkinë e Durrësit, duke adresuar rreziqet kryesore të identifikuara si tërmetet, përmbytjet dhe zjarret pyje, mësuar nga tërmeti i Nëntorit 2019. Plani duhet të përfshijë hartën e rreziqeve dhe vulnerabilitetit komunal, strukturën e qeverisjes së emergjencave dhe rolin e çdo institucioni, protokollet e paralajmërimit të hershëm dhe komunikimit me qytetarët, planin e evakuimit sipas zonave, kapacitetet e strehimit emergjent dhe logjistikën, koordinimin me MBROJTJEN CIVILE dhe forcat e armatosura, planin e rivendosjes pas emergjencës, dhe trajnimin e komunitetit dhe ushtrimet periodike.","tags":["emergency-management","local-government","disaster-risk","albania"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-67","title":"Strategji e Shpërndarjes Digjitale — Gazetë Online Shqipe","prompt":"Jeni konsulent mediash dixhitale me ekspertizë në transformimin e mediave tradicionale shqiptare. Hartoni një strategji të plotë dixhitale dhe të qëndrueshmërisë financiare për një gazetë rajonale të printuar me 20 vjet histori nga Shkodra që dëshiron të kalojë plotësisht në format online. Strategjia duhet të mbulojë analizën e audiencës dhe segmentimin e lexuesve online, modelin e biznesit dixhital si abonimi, reklamimi programatik dhe përmbajtja e sponsorizuar, strategjinë e SEO dhe marketingut të përmbajtjes, platformën teknologjike dhe CMS-in e rekomanduar, ndërtimin e audiencës në rrjete sociale, strategjinë e newsletters dhe push notifications, menaxhimin e ndryshimit organizativ dhe ritrajnimin e gazetarëve, dhe projeksionet financiare 3-vjeçare.","tags":["media","digital-transformation","communications","albania"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-68","title":"Kornizë Etike — Inteligjenca Artificiale në Sektorin Publik","prompt":"Jeni ekspert i etikës së inteligjencës artificiale dhe qeverisjes dixhitale me fokus në vendet e vogla në zhvillim. Hartoni një kornizë etike gjithëpërfshirëse për përdorimin e sistemeve të inteligjencës artificiale në administratën publike të Kosovës, sipas parimeve të AI Act të BE-së dhe standardeve ndërkombëtare. Korniza duhet të mbulojë parimet bazë si transparenca, llogaridhënia dhe jo-diskriminimi, kategorizimin e rrezikut të sistemeve AI sipas përdorimit publik, kërkesat e mbikëqyrjes njerëzore, mbrojtjen e të dhënave personale sipas ligjit kosovar, mekanizmat e ankimit për qytetarët, trajnimin e nëpunësve civilë, dhe planin e zbatimit gradual. Formatoni si dokument politikash i gatshëm për miratim qeveritar.","tags":["artificial-intelligence","governance","digital-transformation","kosovo"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},
    {"id":"sq-69","title":"Plan i Menaxhimit Urban — Qytet i Vogël","prompt":"Jeni urbanist dhe planifikues hapësinor me ekspertizë në qytetet e vogla të Europës Juglindore. Hartoni një plan të menaxhimit urban të integruar 10-vjeçar për qytetin e Peshkopisë me 30,000 banorë, duke adresuar shpërbashkimin demografik dhe rigjallërimin ekonomik. Plani duhet të përfshijë analizën hapësinore dhe demografike aktuale, vizionin e zhvillimit urban dhe prioritetet, projektet e rigjallërimit të qendrës historike, planin e infrastrukturës si uji, kanalizimi dhe rrugët, zonat e aktivitetit ekonomik dhe tregjet publike, hapësirat publike dhe gjelbërimi urban, planin e transportit publik lokal, menaxhimin e trashëgimisë arkitekturore, dhe financimin nga FOND dhe programet e Bankës Botërore. Mbuloni edhe strategjinë e tërheqjes së investimeve.","tags":["urban-planning","local-government","regional-development","albania"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-70","title":"Analizë e Nevojave të Tregut — Sektor IT Kosovar","prompt":"Jeni analist tregu me specializim në sektorin e teknologjisë informative të Kosovës dhe diasporës shqiptare. Kryeni një analizë të plotë të nevojave dhe mundësive të tregut IT kosovar, duke identifikuar ngorçat e talenteve dhe mundësitë e rritjes. Analiza duhet të mbulojë madhësinë dhe rritjen e sektorit IT kosovar me numrin e kompanive dhe punonjësve, profilin e aftësive të kërkuara nga industria kosovare dhe ndërkombëtare, analizën e ofertës arsimore si universitetet dhe bootcamp-et, boshllëqet midis aftësive dhe nevojave të tregut, trendet e outsourcing-ut dhe oportuniteteve të IT nearshoring, pagat dhe kushtet e punës krahasuar me rajonin, dhe rekomandimet për politika arsimore dhe tregtare. Bazoni në të dhënat e MTI-së dhe Invest Kosovo.","tags":["technology","it","market-analysis","kosovo"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-71","title":"Hartim Projekti — Rigjallërim i Trashëgimisë Urbane","prompt":"Jeni arkitekt dhe specialist restaurimi me ekspertizë në trashëgiminë arkitekturore osmane dhe ballkanike. Hartoni një propozim të plotë projekti për rigjallërimin e bllokut historik të çarshisë osmane të Prizrenit, duke ruajtur karakterin autentik historik ndërkohë që krijon hapësira funksionale bashkëkohore. Propozimi duhet të përfshijë analizën historike dhe arkitekturore të bllokut, konceptin e ndërhyrjes me parimet e konservimit, projektet prioritare të restaurimit me metodologji teknike, programimin funksional të ri si dyqane artizanësh, restorant dhe galeri, planet e rijetëzimit ekonomik dhe modelit të menaxhimit, buxhetin e detajuar me burimet e financimit nga Ministria e Kulturës dhe BE, dhe planin e zbatimit me fazat. Formatoni si propozim teknik-kulturor i plotë.","tags":["cultural-heritage","architecture","urban-planning","kosovo"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-72","title":"Strategji Korporative — Kompani e Mesme Shqiptare","prompt":"Jeni konsulent strategjik senior me ekspertizë në transformimin e kompanive të mesme shqiptare për konkurrueshmëri rajonale. Hartoni një strategji korporative 5-vjeçare për një kompani shqiptare të prodhimit të mobiljeve me 80 punonjës dhe xhiro vjetore 2,000,000 euro, që dëshiron të rritet dhe të depërtojë në tregjet e Europës. Strategjia duhet të mbulojë analizën strategjike me SWOT dhe pozicionimin konkurrencial, vizionin dhe objektivat strategjike, strategjinë e produktit dhe inovacionit, strategjinë e hyrjes në tregje të reja si Gjermania dhe Italia, strategjinë e zinxhirit të furnizimit dhe eficiencës operacionale, planin e investimeve dhe financimit, organizimin dhe talentin njerëzor, dhe tablonë e komandimit me KPI-t kryesore. Formatoni si dokument strategjik ekzekutiv.","tags":["business","strategy","sme","albania"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-73","title":"Raport Studimi — Ndikimi i Remitancave në Zhvillim","prompt":"Jeni ekonomist zhvillimi me fokus në ekonomitë e varura nga remitancat të Europës Juglindore. Hartoni një studim akademik të plotë mbi ndikimin e remitancave në zhvillimin ekonomik dhe social të Kosovës, bazuar në të dhënat e dekadës 2014-2024. Studimi duhet të mbulojë metodologjinë e hulumtimit dhe bazën e të dhënave, madhësinë dhe trendet e flukseve të remitancave si % e GDP, analizën e kanaleve të transmetimit ekonomik si konsumi, investimet dhe arsimi, efektet kundërciklike të remitancave gjatë krizave, ndikimin në pabarazinë e të ardhurave dhe tregjesit të punës, krahasimin ndërkombëtar me vende si Meksika dhe Maroku, dhe rekomandimet e politikave për produktivizimin e remitancave. Formatoni si punim shkencor me referencime APA.","tags":["economics","remittances","kosovo","migration"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-74","title":"Doracak Orientimi — Punonjës i Ri në Administratë Publike","prompt":"Jeni specialist i burimeve njerëzore dhe onboarding-ut me ekspertizë në administratën publike kosovare. Hartoni një doracak të plotë orientimi për punonjës të rinj të rekrutuar në Ministrinë e Financave të Kosovës, që mbulon gjithçka që u nevojitet të dinë gjatë 90 ditëve të para të punës. Doracaku duhet të përfshijë historikun dhe misionin e ministrisë, strukturën organizative dhe kontaktet kryesore, legjislacionin kryesor që rregullon punën e ministrisë, procedurat administrative të përditshme si prokurimi dhe raportimi, kodin e etikës dhe integritetit, sistemet informatike dhe platformat e përdorura, të drejtat dhe detyrimet e nëpunësit civil, mundësitë e zhvillimit profesional, dhe burimet e ndihmës dhe mentorimit. Formatoni si doracak praktik i strukturuar mirë.","tags":["public-administration","human-resources","onboarding","kosovo"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-75","title":"Strategji Inovacioni — Ekosistem Startup Shqiptar","prompt":"Jeni ekspert i ekosistemeve të inovacionit dhe politikave të sipërmarrjes me fokus në rajonin e Ballkanit. Hartoni një strategji kombëtare gjithëpërfshirëse për zhvillimin e ekosistemit startup shqiptar 2025-2030, bazuar në vlerësimin e gjendjes aktuale dhe praktikat më të mira ndërkombëtare. Strategjia duhet të mbulojë diagnostikimin e ekosistemit aktual me krahasimin Startup Genome, vizionin dhe pozicionimin e Shqipërisë si hub i rajonit, prioritetet e politikave për financimin, rregullimin dhe tregun e talenteve, zhvillimin e infrastrukturës fizike dhe digjitale si inkubatorët dhe akseleratorët, strategjinë e tërheqjes së diasporës teknologjike, lidhjen me ekosistemit evropiane, financimin nga programet Horizon Europe dhe Invest EU, dhe treguesit e suksesit. Formatoni si strategji kombëtare.","tags":["innovation","startups","entrepreneurship","albania"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},
    {"id":"sq-76","title":"Analiza e Sistemit Gjyqësor — Aksesi në Drejtësi","prompt":"Jeni ekspert i drejtësisë dhe reformës gjyqësore me fokus në Shqipërinë. Hartoni një analizë kritike gjithëpërfshirëse të aksesit në drejtësi për grupet e cenueshme në Shqipëri — grupe me të ardhura të ulëta, romë dhe egjiptianë, dhe banorë ruralë — me rekomandime konkrete. Analiza duhet të mbulojë kuadrin ligjor të ndihmës juridike falas dhe zbatimin e tij, kapacitetin e Drejtorisë së Ndihmës Juridike Falas, barrierat financiare, gjeografike dhe kulturore për akses, analizën e rasteve dhe statistikën gjyqësore sipas grupeve, krahasimin me standardet e Kartës Sociale Evropiane, dhe rekomandimet mbi financimin, kapacitetet dhe sensibilizimin. Bazoni në të dhënat e Ministrisë së Drejtësisë dhe USAID Drejtësia.","tags":["justice","law","governance","albania"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-77","title":"Planifikim Buxhetor Komunal — Buxhetimi Pjesëmarrës","prompt":"Jeni ekspert i financave publike lokale dhe qeverisjes gjithëpërfshirëse. Hartoni një udhëzues praktik dhe metodologji të plotë për zbatimin e buxhetimit pjesëmarrës në Komunën e Mitrovicës Jugore, me popullsi të larmishme dhe buxhet komunal vjetor 8,000,000 euro. Metodologjia duhet të mbulojë parimet e buxhetimit pjesëmarrës sipas praktikave ndërkombëtare, procesin e konsultimit qytetar me fazat dhe formatet, kriteret e zgjedhjes së projekteve dhe vlerësimin teknik, mekanizmin e votimit dhe prioritizimit qytetar, procesin e integrimit në buxhetin zyrtar komunal, komunikimin transparent dhe raportimin publik, planin e kapaciteteve të stafit komunal, dhe lecionet e nxjerra nga raste studimore rajonale. Formatoni si manual zbatimi.","tags":["local-government","participatory-budgeting","governance","kosovo"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-78","title":"Strategji Sportive — Zhvillimi i Futbollit Rinor","prompt":"Jeni konsulent zhvillimi sportiv me ekspertizë në futbollin rinor dhe strukturat e akademive në Europën Juglindore. Hartoni një strategji gjithëpërfshirëse 4-vjeçare për zhvillimin e futbollit rinor në Federatën e Futbollit të Kosovës, me objektiv rritjen e cilësisë dhe standardizimin e akademive të klubeve. Strategjia duhet të mbulojë diagnozën e situatës aktuale të futbollit rinor kosovar, sistemin e licensimit të akademive dhe trajnerëve sipas standardeve UEFA, kurrikulin teknik të zhvillimit sipas grupmoshave U8-U19, sistemin e kompeticioneve rinore, programin e identifikimit dhe talenteve, bashkëpunimin me UEFA HatTrick dhe FIFA Forward, financimin dhe qëndrueshmërinë, dhe treguesit e suksesit afat-shkurtër e afat-gjatë.","tags":["sports","youth","kosovo","development"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-79","title":"Analizë Mbi Korrupsionin — Sektori i Prokurimit Publik","prompt":"Jeni ekspert anti-korrupsion dhe prokurim publik me fokus në Shqipërinë dhe Kosovën. Hartoni një analizë të thellë të rreziqeve të korrupsionit në sistemin e prokurimit publik të Kosovës, bazuar në të dhënat e rasteve dhe auditimet e fundit. Analiza duhet të mbulojë panoramën e sistemit aktual të prokurimit publik, metodologjinë e vlerësimit të rrezikut, identifikimin e 8 pikave kryesore të rrezikut të korrupsionit si ndërhyrjet politike dhe favorizimi i ofertuesve, analizën e rasteve konkrete me tipologjitë e skemave, mekanizmat aktualë të kontrollit dhe boshllëqet, rekomandimet parandaluese teknike dhe institucionale, dhe planin e monitorimit shoqëror. Bazoni në raportet e ZKA-së, PACA-UNODC dhe Transparency International.","tags":["anti-corruption","procurement","governance","kosovo"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-80","title":"Raport i Tregut të Punës — Të Rinjtë NEET","prompt":"Jeni analist i tregut të punës me specializim në punësimin e të rinjve dhe politikat NEET në Ballkanin Perëndimor. Hartoni një analizë të plotë të fenomenit NEET — të rinj që nuk punojnë, nuk studiojnë dhe nuk trajnohen — në Maqedoninë e Veriut, me fokus të veçantë tek komuniteti shqiptar. Analiza duhet të mbulojë madhësinë dhe profilin e popullatës NEET sipas gjinisë, etnisë dhe rajonit, shkaqet strukturore si pengesat arsimore dhe diskriminimi i tregut të punës, ndikimin afat-gjatë ekonomik dhe social, politikat aktuale dhe efektivitetin e tyre, praktikat e suksesshme ndërkombëtare si Garantia Rinore e BE-së, dhe 10 rekomandime konkrete për qeverinë dhe donatorët. Bazoni në të dhënat e DZS dhe ILO Shkup.","tags":["youth","employment","north-macedonia","policy"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-81","title":"Shpjegim i Thjeshtë — Si Funksionon Bashkimi Evropian","prompt":"Shkruani një shpjegim të qartë, angazhues dhe jo-teknik të mënyrës si funksionon Bashkimi Evropian, për lexues shqiptarë dhe kosovarë që nuk kanë njohuri paraprake rreth strukturave të BE-së. Shpjegimi duhet të mbulojë pse u krijua BE-ja dhe cili është qëllimi i saj, si merren vendimet kryesore dhe cilat janë institucionet kryesore si Parlamenti, Komisioni dhe Këshilli, çfarë i ofron BE-ja qytetarëve të saj si liria e lëvizjes, tregu i vetëm dhe fondet, si ndikon BE-ja tek Shqipëria dhe Kosova që janë ende jashtë, çfarë do të thotë anëtarësimi konkretisht dhe si arrihet, dhe mitet dhe keqkuptimet e shpeshta. Toni: informues, i kuptueshëm, i drejtpërdrejtë, me shembuj konkretë nga jeta e përditshme.","tags":["eu-integration","education","citizens","explainer"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-82","title":"Strategji Mbrojtjes Sociale — Grupet e Cenueshme","prompt":"Jeni ekspert i mbrojtjes sociale me fokus në grupet e cenueshme të Shqipërisë. Hartoni një strategji gjithëpërfshirëse 3-vjeçare të mbrojtjes sociale për bashkinë e Fierit me fokus tek katër grupet prioritare: familjet me shumë fëmijë në varfëri, personat e moshuar të vetmuar, personat me aftësi të kufizuara dhe të rinjtë që lënë sistemin e kujdesit. Strategjia duhet të mbulojë profilin dhe madhësinë e secilit grup vulnerable, shërbimet ekzistuese dhe boshllëqet, ndërhyrjet e propozuara për secilin grup me aktivitete dhe buxhet, koordinimin me institucione qendrore dhe OJQ lokale, sistemin e referimit dhe menaxhimit të rasteve, planin e monitorimit dhe vlerësimit, dhe burimet e financimit nga buxheti bashkiak dhe fondet sociale shtetërore.","tags":["social-policy","vulnerable-groups","local-government","albania"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-83","title":"Udhëzues Praktik — Biznes i Vogël dhe Taksat në Shqipëri","prompt":"Jeni kontabilist i licensuar dhe këshilltar tatimor me ekspertizë për bizneset e vogla shqiptare. Hartoni një udhëzues praktik gjithëpërfshirës mbi detyrimet tatimore dhe kontabilitetin bazë për pronarët e rinj të bizneseve të vogla në Shqipëri që sapo kanë regjistruar kompaninë e tyre si person juridik ose tregtar individual. Udhëzuesi duhet të mbulojë llojet e tatimeve — TVSH, tatimi mbi fitimin, tatimi i thjeshtëzuar, kontributet shoqërore — me normativat aktuale, afatet dhe procedurat e deklarimit elektronik tek e-filing, librat kontabël të obligueshme, procedurën e regjistrimit fillestar tek administrata tatimore, gjobat e zakonshme dhe si shmanget, kontrollet tatimore dhe të drejtat e tatimpaguesit, dhe burimet e ndihmës si Dhoma e Tregëtisë. Formatoni me gjuhë të thjeshtë.","tags":["taxation","sme","business","albania"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-84","title":"Plan i Integrimit — Komunitet Romë dhe Egjiptianë","prompt":"Jeni ekspert politikash sociale dhe integrimi me fokus në komunitetet romë dhe egjiptiane të Shqipërisë. Hartoni një plan të detajuar integrimi social 3-vjeçar për komunitetin Romë dhe Egjiptian të bashkisë së Vlorës, me popullatë rreth 2,500 persona, sipas kuadrit të Strategjisë Kombëtare për Integrimin e Romëve 2016-2025. Plani duhet të mbulojë analizën e situatës socioekonomike me tregues të banesave, arsimit dhe punësimit, ndërhyrjet prioritare në arsim si parandalimi i braktisjes, punësimi me trajnime profesionale, dokumentacioni civil dhe aksesi në shërbime, banimi social dhe kushtet e jetesës, lufta kundër diskriminimit dhe ndërgjegjësimit komunitar, strukturën e qeverisjes dhe rolit të mediatorëve komunitar, buxhetin dhe burimet e financimit.","tags":["social-inclusion","roma","local-government","albania"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-85","title":"Analizë Mediale — Liria e Shtypit dhe Mjedisi Mediatik","prompt":"Jeni studiues i medias dhe lirisë së shprehjes me fokus në Ballkanin Perëndimor. Hartoni një analizë të plotë të mjedisit mediatik dhe gjendjes së lirisë së shtypit në Shqipëri për vitin 2024, duke u bazuar në indekset ndërkombëtare dhe evidencën empirike. Analiza duhet të mbulojë panoramën e mediave sipas llojit dhe pronësisë, problemet e koncentrimit të pronësisë dhe pavarësisë editoriale, financimin e mediave dhe varësia nga reklamat publike, kushtet e gazetarëve dhe punësimi i pasigurt, kuadrin ligjor dhe zbatimin e tij, sulmet fizike dhe ligjore ndaj gazetarëve, gjendja e medias online dhe dezinformimi, krahasimin me vendet e rajonit dhe treguesit e RSF, dhe rekomandimet prioritare për reformë. Formatoni si raport analitik me gjetje dhe rekomandime.","tags":["media","freedom-of-press","governance","albania"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-86","title":"Plan Mësimor — Edukimi Financiar për Adoleshentë","prompt":"Jeni edukator financiar me ekspertizë në programet e edukimit financiar për të rinj. Hartoni 8 plane mësimore të plota (45 minuta secili) mbi edukimin financiar bazë për nxënës të klasës 10-12 në shkollat e mesme të Kosovës. Temat: kuptimi i të ardhurave dhe buxhetit personal, kursimet dhe bankat — llojet e llogarive, kreditë konsumatore dhe rreziqet e borxhit, investimet bazë dhe koha e parave, sigurimet dhe mbrojtja financiare, pagesa elektronike dhe fintech, tatimi personal dhe kontributet, dhe planifikimi financiar afat-gjatë. Çdo plan mësimor duhet të ketë objektivat, hyrjen motivuese, shembujt praktikë nga jeta shqiptare, ushtrimet interaktive, dhe pyetjet e vlerësimit. Bazoni në kurrikulin e ri të Kosovës.","tags":["education","financial-literacy","youth","kosovo"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-87","title":"Propozim Teknik — Sistemi i Transportit Publik Urban","prompt":"Jeni inxhinier transporti dhe planifikues urban me ekspertizë në sistemet e transportit publik të qyteteve të mesme. Hartoni një propozim teknik gjithëpërfshirës për modernizimin e sistemit të transportit publik urban të Prishtinës me 220,000 banorë, duke adresuar bllokimet e trafikut dhe ndotjen e ajrit. Propozimi duhet të përfshijë diagnostikimin e sistemit aktual me analizën e flukseve dhe kapacitetit, konceptin e rrjetit të ri autobusëve me linjat dhe frekuencat, studimin e fizibilitetit për BRT — Bus Rapid Transit — në korridorin kryesor, sistemin e biletave dixhitale dhe integrimin multimodal, parkingun park-and-ride, buxhetin e investimit dhe kostot operative, modelin e menaxhimit, financimin nga BERZH dhe Fondi i Klimës, dhe treguesit e ndikimit mjedisor dhe social.","tags":["infrastructure","urban-planning","transport","kosovo"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-88","title":"Analizë e Gjendjes së Diasporës Shqiptare — Gjermani","prompt":"Jeni studiues i migracionit dhe komuniteteve të diasporës me fokus në shqiptarët e Gjermanisë. Hartoni një analizë të plotë socioekonomike dhe kulturore të komunitetit shqiptar në Gjermani, bazuar në të dhënat e disponueshme deri në vitin 2024. Analiza duhet të mbulojë historikun dhe valët e migracionit, madhësinë dhe shpërndarjen gjeografike sipas Länder, profilin demografik dhe arsimor, integrimin ekonomik dhe tregun e punës, integrimin arsimor të fëmijëve, mbajtjen e gjuhës dhe kulturës shqiptare, organizatat dhe institucionet e komunitetit, lidhjet me vendet e origjinës — investimet dhe angazhimi qytetar, dhe rekomandimet e politikave si për Gjermaninë ashtu edhe për Shqipërinë dhe Kosovën.","tags":["diaspora","migration","albania","germany"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-89","title":"Strategji Arsimi i Lartë — Universitete Publike","prompt":"Jeni ekspert i arsimit të lartë me fokus në reformën universitare të vendeve kandidate për BE. Hartoni një strategji gjithëpërfshirëse 5-vjeçare për reformën e Universitetit të Shkodrës Luigj Gurakuqi, duke e transformuar atë në një institucion bashkëkohor me standarde evropiane. Strategjia duhet të mbulojë reformën e qeverisjes akademike dhe autonomisë institucionale, rishikimin e programeve studimore sipas nevojave të tregut të punës, ndërtimin e kapaciteteve kërkimore dhe laboratorëve, strategjinë e internacionalizimit si Erasmus+, partneritetet dhe akreditimet ndërkombëtare, sistemin e sigurimit të cilësisë sipas standardeve ESG, dixhitalizimin e shërbimeve akademike, bashkëpunimin me industrinë dhe pratikat profesionale, dhe planin financiar me diversifikimin e burimeve të të ardhurave. Formatoni si strategji institucionale.","tags":["higher-education","albania","eu-integration","academic"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-90","title":"Guidë Kulturore — Festa dhe Tradita Shqiptare","prompt":"Jeni etnograf dhe specialist i kulturës materiale dhe jomateriale shqiptare. Hartoni një guidë kulturore gjithëpërfshirëse dhe angazhuese mbi festat, traditat dhe zakonet e rëndësishme të kulturës shqiptare, të destinuara për lexuesit e diasporës dhe turistët e huaj. Guida duhet të mbulojë festat kombëtare dhe historike si 28 Nëntori dhe 17 Shkurti, festat fetare kryesore si Bajrami, Krishtlindjet dhe Shën Gjini, zakonet e martesës dhe ceremonitë tradicionale, gastronomia dhe ritualet e ushqimit, muzika dhe vallet tradicionale si iso-polifonia dhe vallja shqipe, Kanuni i Lekë Dukagjinit dhe institucionet kulturore si Besa dhe Mikpritja, traditat e ndryshme rajonale, dhe mënyrat si diaspora i ruan këto tradita. Toni: informues, respektues, i pasur kulturalisht.","tags":["culture","albanian-culture","traditions","diaspora"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-91","title":"Analiza e Politikës Energjetike — Tranzicioni Energjetik","prompt":"Jeni ekspert i politikave energjetike me fokus në tranzicionin energjetik të vendeve të vogla importuese të energjisë. Hartoni një analizë të plotë të situatës energjetike dhe rrugës së tranzicionit të Shqipërisë drejt energjisë 100% të rinovueshme dhe neutralitetit karbonit deri në 2050. Analiza duhet të mbulojë matricën aktuale energjetike me varësinë nga hidroenergjia dhe sfidat e thatësirës, potencialin e energjisë diellore dhe të erës sipas rajonit, infrastrukturën e rrjetit elektrik dhe nevojat e modernizimit, kuadrin rregullator dhe politikat e stimulimit, integrimin me tregun energjetik rajonal dhe ENTSO-E, financimin e tranzicionit nga fondet e klimës dhe IFI-të, ndikimin social dhe programet e tranzicionit të drejtë, dhe rekomandimet e politikave prioritare. Bazoni në strategjinë energjetike 2030 të Shqipërisë.","tags":["energy","environment","policy","albania"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-92","title":"Plan Suksesioni — Biznes Familjar Shqiptar","prompt":"Jeni konsulent biznesi dhe jurist me ekspertizë në transferimin dhe qëndrueshmërinë e bizneseve familjare shqiptare. Hartoni një plan të plotë suksesioni për një kompani familjare ndërtimi me 60 punonjës nga Tirana, e themeluar në vitin 1995 nga babai themelues i cili është 68 vjeç, duke kaluar drejtimin tek vajza 38-vjeçare me arsim inxhinierik dhe MBA. Plani duhet të mbulojë vlerësimin e biznesit dhe strukturën e pronësisë, profilin e kompetencave të trashëgimtares dhe boshllëqet e zhvillimit, planin e transferimit gradual të roleve dhe autoritetit, trajtimin ligjor dhe fiskal të transferimit të pronësisë, komunikimin me stafin dhe partnerët, menaxhimin e konflikteve potenciale familjare, qeverisjen e re me bordin këshillues, dhe sigurimin e kontinuitetit operacional gjatë tranzicionit.","tags":["business","family-business","succession","albania"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-93","title":"Analizë Kushtetuese — E Drejta e Minoriteteve","prompt":"Jeni jurist kushtetues specialist i të drejtave të minoriteteve me fokus në Ballkanin Perëndimor. Hartoni një analizë të plotë kushtetuese dhe ligjore të mbrojtjes së të drejtave të komunitetit shqiptar si minoritet në Maqedoninë e Veriut, pas Marrëveshjes së Ohrit 2001 dhe ndryshimeve kushtetuese 2019. Analiza duhet të mbulojë kuadrin kushtetues dhe ligjor të mbrojtjes së minoriteteve, zbatimin praktik të të drejtave gjuhësore, arsimore dhe politike, Badinter-in dhe mekanizmat e mbrojtjes institucionale, progresin dhe sfidat 20 vjet pas Ohrit, krahasimin me standardet e Konventës Kuadër të KE-së, rastet gjyqësore dhe çështjet e pazgjidhura, dhe rekomandimet e reformave të mëtejshme. Formatoni si analizë ligjore akademike.","tags":["law","minority-rights","north-macedonia","governance"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-94","title":"Strategji Shëndetësore — Kujdesi Parësor Shëndetësor","prompt":"Jeni ekspert i sistemeve shëndetësore me fokus në kujdesin parësor të Kosovës. Hartoni një strategji gjithëpërfshirëse 5-vjeçare për forcimin e kujdesit parësor shëndetësor në Kosovë, duke adresuar pabarazinë rajonale dhe cilësinë e shërbimeve. Strategjia duhet të mbulojë diagnostikimin e sistemit aktual me treguesit kryesorë shëndetësorë, kapacitetet e Qendrave Mjekësore Familjare sipas komunave, planin e rekrutimit dhe mbajtjes së mjekëve familjarë në zonat rurale, standardizimin e protokolleve klinike dhe udhëzuesve praktike, integrimin e shërbimeve mendore dhe sociale, sistemin e referimit dhe koordinimit me nivelet e tjera, dixhitalizimin e kartelës elektronike shëndetësore, financimin e bazuar në performancë, dhe treguesit e ndikimit shëndetësor. Bazoni në të dhënat e MSh-së dhe WHO.","tags":["healthcare","public-health","kosovo","policy"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-95","title":"Analiza e Nevojave — Komunitet Lokal","prompt":"Jeni specialist vlerësimi nevojash dhe zhvillimi komunitar me ekspertizë në metodologjitë participative. Kryeni një analizë të plotë të nevojave të komunitetit për [Përshkruani komunitetin tuaj: vendndodhja, popullsia, konteksti specifik], duke identifikuar prioritetet e zhvillimit nga perspektiva e banorëve. Analiza duhet të mbulojë metodologjinë e mbledhjes së informacionit si intervistat, grupet e fokusit dhe anketat, profilin socioekonomik të komunitetit, nevojat e identifikuara sipas sektorëve si infrastruktura, shërbime sociale, arsimi dhe punësimi, kapacitetet dhe resurset ekzistuese lokale, prioritetet e komunitetit të renditura sipas urgjencës dhe rëndësisë, dhe rekomandimet konkrete me projekt-idetë e propozuara. Formatoni si raport analize nevojash i gatshëm për financuesit.","tags":["community-development","needs-assessment","local-government","participatory"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-96","title":"Strategji Ripopullimi — Zonat Rurale","prompt":"Jeni ekspert i demografisë dhe zhvillimit rural me fokus në zbrazjen rurale të Ballkanit. Hartoni një strategji gjithëpërfshirëse anti-zbrazje dhe ripopullimi rural për rajonin e Kukësit, duke adresuar emigracionin masiv dhe plakjen e popullsisë. Strategjia duhet të mbulojë analizën demografike dhe projeksionet e zbrazjes sipas skenarëve, stimujt ekonomikë për kthimin dhe vendosjen e familjeve si subvencionet e banesës dhe biznesit, zhvillimin e infrastrukturës si interneti me brez të gjerë, rrugët dhe shëndetësia, programet e tërheqjes së diasporës për investime dhe kthim, bashkëpunimin me universitetet për punësimin e diplomuarëve lokalë, modelet e suksesshme europiane si politikat rurale të Austrisë dhe Norvegjisë, financimin nga fondet e BE-së, dhe treguesit e suksesit demografik afat-gjatë.","tags":["rural-development","demography","albania","migration"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-97","title":"Plan Biznesi — [Përshkruani idenë tuaj të biznesit]","prompt":"Jeni konsulent biznesi senior me 20 vjet përvojë në hapjen e bizneseve të reja dhe konsultimin e sipërmarrësve shqiptarë. Hartoni një plan biznesi të plotë dhe professional për [Përshkruani idenë tuaj të biznesit: lloji i biznesit, vendndodhja, tregu i synuar dhe investimi i planifikuar]. Plani duhet të përfshijë: Përmbledhjen Ekzekutive me konceptin dhe propozimin e vlerës, Analizën e Tregut me madhësinë dhe konkurrencën, Strategjinë e Marketingut dhe kanaleve të shitjes, Planin Operacional me proceset dhe burimet njerëzore, Projeksionet Financiare 3-vjeçare me të ardhura, shpenzime dhe cash flow, Analizën e Rreziqeve dhe masat zbutëse, dhe Planin e Financimit me burimet e kapitalit. Formatoni si dokument professional i gatshëm për prezantim para bankave dhe investitorëve.","tags":["business","entrepreneurship","planning","albania"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},
    {"id":"sq-98","title":"Propozim Projekti — [Përshkruani projektin tuaj]","prompt":"Jeni menaxher projekti me ekspertizë të gjerë në formulimin dhe zbatimin e projekteve të financuara nga BE dhe donatorë ndërkombëtalë në rajonin e Ballkanit. Hartoni një propozim të plotë projekti sipas standardeve ndërkombëtare për [Përshkruani projektin tuaj: qëllimi, grupi i synuar, zona gjeografike dhe buxheti i parashikuar]. Propozimi duhet të përfshijë: Analizën e Situatës me kontekstin dhe problemin e adresuar, Teorinë e Ndryshimit dhe Logjikën e Ndërhyrjes, Objektivat e Përgjithshëm dhe Specifik, Rezultatet e Pritura me tregues SMART, Aktivitetet e Detajuara me planin kohor, Buxhetin e Plotë me justifikim, Planin e Monitorimit dhe Vlerësimit, Strategjinë e Qëndrueshmërisë, dhe Menaxhimin e Rreziqeve. Formatoni sipas formatit standard PCM.","tags":["project-management","donors","civil-society","regional-development"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-99","title":"Analizë Strategjike — [Përshkruani organizatën ose sektorin tuaj]","prompt":"Jeni konsulent strategjik me ekspertizë të gjerë në analizën organizative dhe sektoriale të rajonit të Ballkanit Perëndimor. Kryeni një analizë strategjike të plotë për [Përshkruani organizatën ose sektorin tuaj: emri, misioni, madhësia, konteksti operativ], duke ofruar rekomandime praktike dhe të zbatueshme. Analiza duhet të përfshijë: Analizën e Jashtme me faktorët PESTEL dhe mundësitë e rreziqet e tregut, Analizën e Brendshme me kapacitetet dhe resurset kryesore, Matricën SWOT të plotë me lidhjet midis faktorëve, Analizën e Palëve të Interesit me hartën e ndikimit dhe interesit, Alternativat Strategjike me vlerësimin e çdo opsioni, Rekomandimet Prioritare me argumentimin dhe planin e zbatimit, dhe Treguesit e Suksesit. Formatoni si raport strategjik ekzekutiv.","tags":["strategy","analysis","business","governance"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"sq-100","title":"Letër Ankese ose Kërkesë Zyrtare","prompt":"Jeni specialist i komunikimit zyrtar dhe dokumentacionit administrativ me njohuri të plota të procedurave administrative shqiptare dhe kosovare. Hartoni një letër zyrtare të plotë dhe efektive — ankese ose kërkesë — drejtuar [Përshkruani situatën tuaj: cilit institucion i drejtoheni, cili është problemi ose kërkesa juaj dhe çfarë rezultati prisni]. Letra duhet të përfshijë: Kreun me të dhënat e dërguesit dhe marrësit sipas formatit zyrtar, Objektin e qartë dhe konciz, Ekspozën me parashtrimin e fakteve kronologjikisht, Bazën Ligjore me nenin ose ligjin përkatës, Kërkesën konkrete dhe të matshme, Afatin e pritshëm të përgjigjes, Bashkëngjitjet relevante të listuara, dhe Nënshkrimin me datën. Toni: i qetë, profesional, bindës dhe ligjërisht korrekt.","tags":["administration","legal","citizens","albania"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false}
];
  __exports.albanianPrompts = albanianPrompts;
})();